/* Explicit stair-stack authoring. Pure proposals are previewed before one atomic edit. */
(function(root){
'use strict';
const clone=x=>JSON.parse(JSON.stringify(x)),box=r=>({x:r.x,y:r.y,w:r.w,h:r.h}),arr=x=>Array.isArray(x)?x:[];
function id(plan,prefix){let n=1,value;do{value=prefix+n++}while(Object.values(plan.floors).some(f=>f.rooms.some(r=>r.id===value))||arr(plan.verticalConnections).some(c=>c.id===value));return value}
function linked(plan,floor,room){return arr(plan.verticalConnections).find(c=>c?.type==='stair'&&c.room===room&&arr(c.floors).includes(floor))}
function prepare(plan,input){
 const next=clone(plan),fid=input.floorId,source=next.floors[fid]?.rooms.find(r=>r.id===input.roomId),existing=source?linked(next,fid,source.id):null;
 const floors=[...new Set(input.floors||[])];if(!floors.includes(fid))throw Error('Keep the current floor selected.');if(floors.length<2)throw Error('Choose at least two floors. Add another floor in Manage if needed.');if(floors.some(k=>!Object.hasOwn(next.floors,k)||!Number.isFinite(next.floors[k].z)))throw Error('Every connected floor needs a finite elevation.');const elevation=f=>{const r=source?next.floors[f]?.rooms.find(r=>r.id===source.id):null;return Number.isFinite(r?.z)?r.z:next.floors[f].z};floors.sort((a,b)=>elevation(a)-elevation(b));
 for(let i=1;i<floors.length;i++)if(elevation(floors[i])===elevation(floors[i-1]))throw Error('Two selected floors have the same elevation. Change a floor elevation first.');
 const footprint={};for(const k of ['x','y','w','h']){const v=Number(input[k]);if(!Number.isFinite(v)||Math.abs(v)>150||Math.abs(v*1e6-Math.round(v*1e6))>1e-4||(['w','h'].includes(k)&&v<1))throw Error('Use positive dimensions and coordinates within ±150 m.');footprint[k]=v}
 const name=String(input.name||source?.name||'Stairs').trim().slice(0,150)||'Stairs',runAxis=input.runAxis||'x',landingEnd=input.landingEnd||(runAxis==='x'?'west':'north');if(!['x','y'].includes(runAxis)||!(runAxis==='x'?['west','east']:['north','south']).includes(landingEnd))throw Error('Choose a matching flight direction and arrival end.');
 const stairType=input.stairType||source?.stairType||existing?.stairType||'switchback',spiralHand=input.spiralHand||source?.spiralHand||existing?.spiralHand||'right';if(!['switchback','straight','spiral'].includes(stairType))throw Error('Choose a supported stair type. Scissor stairs are not supported.');if(!['left','right'].includes(spiralHand))throw Error('Choose a spiral ascent direction.');if(stairType==='straight'&&floors.length!==2)throw Error('Straight stairs connect exactly two floors. Create separate stacks for more destinations.');
 if(source&&!existing&&(source.linkedSource||source.type==='void'||source.type==='solid'||source.locked))throw Error('This protected footprint cannot be converted.');
 if(source&&!existing&&arr(next.splitLevelConnections).some(c=>c.room===source.id&&c.floor===fid))throw Error('This is a local split-level stair. Its two room elevations are already connected; create a separate stack.');
 const roomId=source?.id||id(next,'stairs-'),stackId=existing?.id||id(next,'stair-stack-');
 if(!existing&&source&&arr(next.verticalConnections).some(c=>c.room===source.id))throw Error('This room already belongs to a vertical connection.');
 for(const f of floors){const r=next.floors[f].rooms.find(r=>r.id===roomId);if(r&&!(existing?.floors.includes(f)||f===fid&&source))throw Error(f+': a different room has the same ID. Choose a different source room.');if(!r&&next.floors[f].rooms.length>=300)throw Error(f+': floor has reached 300 rooms.');}
 const notices=[];for(const f of existing?.floors||[])if(!floors.includes(f)){const level=next.floors[f],r=level?.rooms.find(r=>r.id===roomId);if(r){if(r.stairOriginal){const original=clone(r.stairOriginal);Object.keys(r).forEach(k=>delete r[k]);Object.assign(r,original)}else{level.rooms=level.rooms.filter(r=>r.id!==roomId);level.doors=level.doors.filter(d=>d.a!==roomId&&d.b!==roomId);level.entrances=level.entrances.filter(r=>r!==roomId);if(level.externals)level.externals=level.externals.filter(e=>e.room!==roomId);if(level.external?.room===roomId)delete level.external}notices.push(f+': the stair footprint and its access connections will be removed.')}}
 const con={...(existing||{}),id:stackId,type:'stair',room:roomId,floors,footprint:clone(footprint),footprints:{},runAxis,landingEnd,authoringVersion:1};
 con.stairType=stairType;con.spiralHand=spiralHand;
 for(const f of floors){const level=next.floors[f];let r=level.rooms.find(r=>r.id===roomId);if(!r){r={id:roomId,name,type:'core',...footprint,stairCreated:true};level.rooms.push(r)}else if(!existing&&!r.stairOriginal){r.stairOriginal=clone(r)}Object.assign(r,footprint,{name,type:'core',runAxis,landingEnd,editGroup:stackId,stairStackId:stackId,stairTransition:true,locked:false});if(r.diagramLabel!==undefined)r.diagramLabel=name;delete r.lowerZ;delete r.upperZ;con.footprints[f]=box(r)}
 next.verticalConnections=arr(next.verticalConnections).filter(c=>c.id!==stackId);next.verticalConnections.push(con);
 for(const f of floors)Object.assign(next.floors[f].rooms.find(r=>r.id===roomId),{stairType,spiralHand});
 const min=elevation(floors[0]),max=elevation(floors.at(-1)),passed=Object.entries(next.floors).filter(([f,l])=>!floors.includes(f)&&l.z>min&&l.z<max).map(([f])=>f);con.passedFloors=passed;
 for(const f of [...floors,...passed])for(const r of next.floors[f].rooms){if(r.id===roomId||r.type==='void')continue;const w=Math.min(r.x+r.w,footprint.x+footprint.w)-Math.max(r.x,footprint.x),h=Math.min(r.y+r.h,footprint.y+footprint.h)-Math.max(r.y,footprint.y);if(w>1e-6&&h>1e-6)notices.push(f+': stair shaft overlaps '+r.name+'. Move the stair or make a clear opening; the route is not verified.')}
 for(const f of passed)notices.push(f+': passes through this floor without access. The required slab / services / ceiling opening must remain clear.');
 return {plan:next,roomId,stackId,floors,passedFloors:passed,notices,connection:con};
}
function remove(plan,stackId){const next=clone(plan),c=arr(next.verticalConnections).find(c=>c.id===stackId&&c.type==='stair');if(!c)return next;for(const fid of c.floors){const f=next.floors[fid];if(!f)continue;f.rooms=f.rooms.filter(r=>r.id!==c.room);f.doors=f.doors.filter(d=>d.a!==c.room&&d.b!==c.room);f.entrances=f.entrances.filter(id=>id!==c.room);if(f.externals)f.externals=f.externals.filter(e=>e.room!==c.room);if(f.external?.room===c.room)delete f.external}next.verticalConnections=next.verticalConnections.filter(v=>v.id!==stackId);return next}
const api={prepare,remove,linked};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.KERN_STAIR_AUTHOR=api;
})(typeof window!=='undefined'?window:globalThis);
